BEGIN;SET LOCAL lock_timeout='15s';SET LOCAL statement_timeout='10s';SET LOCAL work_mem='32MB';SET LOCAL jit=off;DO $natural$ DECLARE v_until timestamptz:=clock_timestamp()+interval '8 seconds';v_locked boolean;BEGIN LOOP
BEGIN v_locked:=pg_try_advisory_xact_lock(2026083000261022);IF NOT v_locked THEN RAISE EXCEPTION 'D02_V3_BUSY_SENTINEL';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED')OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE outcome='RUNNING'OR ended_at IS NULL)OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL)OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL)OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_job WHERE status='RUNNING')THEN RAISE EXCEPTION 'D02_V3_BUSY_SENTINEL';END IF;EXIT;
EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM IS DISTINCT FROM 'D02_V3_BUSY_SENTINEL' THEN RAISE;END IF;END;
IF clock_timestamp()>=v_until THEN RAISE EXCEPTION 'D02_V3_BOUNDED_NATURAL_GAP_UNAVAILABLE';END IF;PERFORM pg_sleep(0.15);END LOOP;END $natural$;
DO $guard$
DECLARE ac population_top3000_202608_202609_v1.acquisition_control%rowtype; pc population_top3000_202608_202609_v1.pipeline_control%rowtype; a jsonb;c jsonb;
BEGIN
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED')
OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE outcome='RUNNING' OR ended_at IS NULL)
OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL)
OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL)
OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_job WHERE status='RUNNING')
THEN RAISE EXCEPTION 'D02_POINT_NATURAL_QUIET_REQUIRED'; END IF;
SELECT * INTO STRICT ac FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
SELECT * INTO STRICT pc FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
SELECT details INTO STRICT a FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=83312 AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
SELECT details INTO STRICT c FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=83347 AND event='ENGINEERING_ASSIGNMENT_CLAIMED_V5';
IF (ac.owner_id='top3000-completion-20261024-root-5db48b32d103' AND ac.owner_fence=3 AND ac.stop_generation=1 AND ac.enabled AND NOT ac.stopped AND ac.hold_reason IS NULL
AND ac.admitted_until>clock_timestamp() AND pc.enabled AND pc.deadline>clock_timestamp()
AND ac.scope_sha256='8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd'
AND pc.expected_owner_id=ac.owner_id AND pc.expected_owner_fence=ac.owner_fence AND pc.expected_stop_generation=ac.stop_generation AND pc.scope_sha256=ac.scope_sha256
AND c->>'assignment_event_id'='83312' AND c->>'assignment_details_sha256'='909c438fcfb764347a89e5b6a26d734293bbc7ad9158c8dd1951b321745b63cd'
AND encode(sha256(convert_to(a::text,'UTF8')),'hex')='909c438fcfb764347a89e5b6a26d734293bbc7ad9158c8dd1951b321745b63cd' AND c->>'executor'='automation:6adc2c96db348191bca7cf4eacfdac32'
AND (c->>'expires_at')::timestamptz>clock_timestamp() AND (a->>'not_after')::timestamptz>clock_timestamp()
AND EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=81090 AND event='USER_POST_DEADLINE_CONTINUATION_AUTHORITY_V1' AND details->>'owner_id'=ac.owner_id AND details->>'scope_sha256'=ac.scope_sha256 AND details->>'stop_generation'='1')
AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event IN('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND details->>'claim_event_id'='83347')) IS DISTINCT FROM TRUE
THEN RAISE EXCEPTION 'D02_POINT_CURRENT_CLAIM'; END IF;
IF encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.ctx06_aug03_check_v5(boolean,text)'::regprocedure),'UTF8')),'hex') IS DISTINCT FROM '182c4ece2975b98fc114fda6f904aae832d05a58221f19271d55e50f1b314afd' THEN RAISE EXCEPTION 'D02_POINT_ASSERTION_HELPER_PIN';END IF;
END $guard$;
CREATE TEMP TABLE d02_batch_clock ON COMMIT DROP AS SELECT clock_timestamp()started;
CREATE TEMP TABLE d02_candidate ON COMMIT DROP AS WITH pin AS MATERIALIZED(SELECT * FROM jsonb_to_recordset($pins$__SOURCE_PIN_JSON__$pins$::jsonb) AS x(day bigint,date date,id text,sha text,n int,verified int)),
calendarpin AS MATERIALIZED(SELECT * FROM jsonb_to_recordset($calendarpins$__CALENDAR_PIN_JSON__$calendarpins$::jsonb) AS x(date date,scope text,source_calendar_manifest_sha256 text,record_sha256 text,receipt_sha256 text,qualification text)),
anchors AS MATERIALIZED(SELECT * FROM population_top3000_202608_202609_v1.working_accepted_companies_v1),
ap AS MATERIALIZED(SELECT p.*,count(*)OVER(PARTITION BY company_id) n FROM population_top3000_202608_202609_v1.ref01_practical_instrument_point_v3 p
WHERE p.cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND p.eligible AND p.point_date='2026-08-03'),
days AS MATERIALIZED(SELECT s.*,d.content_text::jsonb body,(s.source_sha256=d.source_sha256 AND d.source_sha256=encode(sha256(convert_to(d.content_text,'UTF8')),'hex') AND d.content_bytes=octet_length(d.content_text)
AND d.source_uri='https://api.massive.com/v2/aggs/grouped/locale/us/market/stocks/'||s.session_date::text||'?adjusted=false&include_otc=false' AND s.source_id=x.id AND s.source_sha256=x.sha AND s.result_count=x.n AND s.verified_source_records=x.verified AND d.source_provider='Massive'
AND jsonb_typeof(d.content_text::jsonb->'results')='array' AND jsonb_array_length(d.content_text::jsonb->'results')=x.n)IS TRUE body_ok
FROM pin x JOIN population_top3000_202608_202609_v1.d02_daily_source_v2 s ON s.source_day_id=x.day AND s.session_date=x.date JOIN population_top3000_202608_202609_v1.source_document d ON d.source_id=s.source_id),
calendarchecks AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5((count(*)=1 AND bool_and(c.source_record_sha256=cp.record_sha256 AND c.source_receipt_sha256=cp.receipt_sha256 AND c.qualification=cp.qualification AND c.source_record_sha256=encode(sha256(convert_to(c.source_record_text,'UTF8')),'hex') AND c.source_receipt_sha256=encode(sha256(convert_to(c.source_receipt_text,'UTF8')),'hex') AND ds.calendar_scope_id=cp.scope AND ds.calendar_manifest_sha256=cp.source_calendar_manifest_sha256))IS TRUE,'D02_EXACT_CALENDAR_PINS')ok FROM calendarpin cp JOIN population_top3000_202608_202609_v1.catalog_calendar c ON c.session_date=cp.date AND c.scope_id=cp.scope JOIN days ds ON ds.session_date=cp.date),
sourcechecks AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5((count(*)=1 AND count(DISTINCT session_date)=1 AND bool_and(body_ok IS TRUE) AND sum(result_count)=(SELECT sum(n) FROM pin))IS TRUE,'D02_EXACT_ONE_SOURCE_HEADER_PINS')ok FROM days),
anchorchecks AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5((count(*)=3000 AND count(DISTINCT company_id)=3000 AND count(DISTINCT selection_order)=3000 AND min(selection_order)=1 AND max(selection_order)=3000 AND bool_and(membership_accepted AND cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND membership_acceptance_sha256='20b9dac759857e9b510ccaeca33e4a94d8c748d588fb0cc27740cc66c389b5f9'))IS TRUE,'D02_EXACT_3000_ACCEPTED_ANCHORS')ok FROM anchors),
raw_daily AS MATERIALIZED(SELECT ds.source_day_id,x.rec,x.ord::int source_row,x.rec->>'T' ticker,count(*)OVER(PARTITION BY ds.source_day_id,x.rec->>'T') n FROM days ds CROSS JOIN LATERAL jsonb_array_elements(ds.body->'results')WITH ORDINALITY x(rec,ord) WHERE x.rec->>'T' IN(SELECT anchor_ticker FROM anchors)),
raw_counts AS MATERIALIZED(SELECT source_day_id,ticker,max(n)::integer actual_source_rows FROM raw_daily GROUP BY source_day_id,ticker),
points AS MATERIALIZED(SELECT p.*,count(*)OVER(PARTITION BY company_id,point_date) n FROM population_top3000_202608_202609_v1.ref01_practical_dated_instrument_v3 p
WHERE p.cohort_sha256='2dc0f766befed6de6b052221c3c87482d507ba1bad931cbb98654eb3af899bec' AND p.point_date IN(SELECT session_date FROM days)),
refdocs AS MATERIALIZED(SELECT d.source_id,d.source_sha256,d.evidence->>'as_of' reference_date,d.content_text::jsonb body,
(d.source_sha256=encode(sha256(convert_to(d.content_text,'UTF8')),'hex') AND d.content_bytes=octet_length(d.content_text) AND d.source_provider='Massive')IS TRUE body_ok
FROM population_top3000_202608_202609_v1.source_document d WHERE d.source_id IN(SELECT p.content->>'source_id' FROM points p)),
refraw AS MATERIALIZED(SELECT rd.source_id,rd.source_sha256,rd.reference_date,rd.body_ok,x.ord::integer ordinal,x.rec rawref FROM refdocs rd CROSS JOIN LATERAL jsonb_array_elements(rd.body->'results')WITH ORDINALITY x(rec,ord) WHERE x.rec->>'ticker' IN(SELECT anchor_ticker FROM anchors)),
legacy_docs AS MATERIALIZED(SELECT r.job_id,r.sha256,r.raw_text::jsonb body,(r.sha256=encode(sha256(convert_to(r.raw_text,'UTF8')),'hex')AND r.source_bytes=octet_length(r.raw_text))IS TRUE body_ok FROM(SELECT DISTINCT source_job_id FROM ap WHERE n=1 AND EXISTS(SELECT 1 FROM days WHERE session_date=DATE '2026-08-03'))x JOIN population_top3000_202608_202609_v1.acquisition_raw r ON r.job_id=x.source_job_id),
legacy_raw AS MATERIALIZED(SELECT d.job_id,d.sha256,d.body_ok,x.rec,x.ord::integer ordinal FROM legacy_docs d CROSS JOIN LATERAL jsonb_array_elements(d.body->'results')WITH ORDINALITY x(rec,ord)WHERE x.rec->>'ticker' IN(SELECT anchor_ticker FROM anchors)),
joined AS MATERIALIZED(SELECT a.selection_order,a.company_id,a.anchor_ticker,a.anchor_composite_figi,a.anchor_share_class_figi,a.anchor_security_type,a.anchor_exchange,ds.session_date,ds.source_day_id,ds.body_ok daily_body_ok,
p.n pn,p.content pc,p.record_sha256 pointsha,p.source_set_sha256,p.ticker pticker,ap.n an,ap.content ac,ap.record_sha256 anchorsha,
r.content rc,r.record_sha256 refsha,r.ordinal refordinal,rd.body_ok refbody_ok,rd.source_sha256 refbodysha,rd.reference_date,rd.rawref,ap.source_job_id legacy_job,lad.body_ok legacy_body_ok,lad.sha256 legacy_bodysha,lad.rec legacy_rec,lad.ordinal legacy_ord,
rcnt.actual_source_rows,raw.n rn,raw.rec dailyrec,raw.source_row,b.source_ticker,b.provider_time_ms,b.provider_ny_date,b.provider_close,b.share_volume,b.provider_vwap,b.missing_mask,b.invalid_mask,b.structure_mask,b.raw_record_sha256
FROM anchors a CROSS JOIN days ds CROSS JOIN sourcechecks sc CROSS JOIN anchorchecks ach CROSS JOIN calendarchecks cc
LEFT JOIN ap ON ap.company_id=a.company_id AND ap.n=1 LEFT JOIN points p ON p.company_id=a.company_id AND p.point_date=ds.session_date AND p.n=1
LEFT JOIN population_top3000_202608_202609_v1.ref01_date_record_v4 r ON r.source_id=p.content->>'source_id' AND r.ordinal=(p.content->>'source_ordinal')::integer
LEFT JOIN refraw rd ON rd.source_id=r.source_id AND rd.ordinal=r.ordinal LEFT JOIN legacy_raw lad ON lad.job_id=ap.source_job_id AND lad.ordinal=ap.source_ordinal
LEFT JOIN raw_counts rcnt ON rcnt.source_day_id=ds.source_day_id AND rcnt.ticker=a.anchor_ticker LEFT JOIN raw_daily raw ON raw.source_day_id=ds.source_day_id AND raw.ticker=a.anchor_ticker AND raw.n=1
LEFT JOIN population_top3000_202608_202609_v1.d02_daily_bar_v2 b ON b.source_day_id=raw.source_day_id AND b.source_row=raw.source_row WHERE sc.ok AND ach.ok AND cc.ok),
classified AS MATERIALIZED(SELECT j.*,CASE
WHEN pn IS DISTINCT FROM 1 THEN 'MISSING_OR_AMBIGUOUS_DATED_POINT'
WHEN ((session_date=DATE '2026-08-03' AND an=1 AND anchorsha=encode(sha256(convert_to(ac::text,'UTF8')),'hex') AND pointsha=encode(sha256(convert_to(pc::text,'UTF8')),'hex') AND legacy_body_ok AND source_set_sha256='27c81878e9ea5ce6eb05ead025f5c9aaae11108af50ba59ecd65b3402c877c86' AND pc->>'identity_basis'='REVIEWED_FROZEN_IDENTITY_POINT' AND pc->>'point_record_sha256'=anchorsha AND pc->>'source_job_id'=legacy_job AND(pc->>'source_ordinal')::integer=legacy_ord AND pc->>'source_sha256'=legacy_bodysha AND ac->>'source_sha256'=legacy_bodysha AND pc->>'source_record_sha256'=encode(sha256(convert_to(legacy_rec::text,'UTF8')),'hex') AND ac->'source_record'=legacy_rec AND pc->>'company_id'=company_id AND pc->>'point_date'=session_date::text AND pticker=anchor_ticker AND legacy_rec->>'ticker'=anchor_ticker AND nullif(legacy_rec->>'composite_figi','')=anchor_composite_figi AND nullif(legacy_rec->>'share_class_figi','')=anchor_share_class_figi AND nullif(legacy_rec->>'cik','')IS NOT NULL AND nullif(ac#>>'{source_record,cik}','')IS NOT NULL AND legacy_rec->>'cik'=ac#>>'{source_record,cik}' AND legacy_rec->>'type'=anchor_security_type AND legacy_rec->>'primary_exchange'=anchor_exchange AND legacy_rec->>'active'='true' AND legacy_rec->>'market'='stocks' AND legacy_rec->>'locale'='us') OR (session_date<>DATE '2026-08-03' AND (an=1 AND anchorsha=encode(sha256(convert_to(ac::text,'UTF8')),'hex') AND pointsha=encode(sha256(convert_to(pc::text,'UTF8')),'hex')
AND refsha=encode(sha256(convert_to(rc::text,'UTF8')),'hex') AND refsha=pc->>'source_record_sha256' AND refbody_ok AND source_set_sha256=refbodysha
AND reference_date=session_date::text AND rc->>'point_date'=session_date::text AND rc->>'company_id'=company_id AND rc->'source_record'=rawref AND pc->>'anchor_record_sha256'=anchorsha AND pc->>'company_id'=company_id AND pc->>'point_date'=session_date::text
AND pticker=anchor_ticker AND rawref->>'ticker'=anchor_ticker AND nullif(rawref->>'composite_figi','')=anchor_composite_figi AND nullif(rawref->>'share_class_figi','')=anchor_share_class_figi
AND nullif(rawref->>'cik','') IS NOT NULL AND nullif(ac#>>'{source_record,cik}','') IS NOT NULL AND rawref->>'cik'=ac#>>'{source_record,cik}' AND rawref->>'type'=anchor_security_type AND rawref->>'primary_exchange'=anchor_exchange
AND rawref->>'active'='true' AND rawref->>'market'='stocks' AND rawref->>'locale'='us'))) IS DISTINCT FROM TRUE THEN 'POINT_RAW_ANCHOR_MISMATCH'
WHEN rn IS DISTINCT FROM 1 THEN 'MISSING_OR_DUPLICATE_SOURCE_TICKER'
WHEN (daily_body_ok AND source_ticker=anchor_ticker AND provider_ny_date=session_date AND missing_mask=0 AND invalid_mask=0 AND structure_mask=0
AND provider_time_ms=(dailyrec->>'t')::numeric AND raw_record_sha256=sha256(convert_to(dailyrec::text,'UTF8')) AND provider_close=(dailyrec->>'c')::numeric AND share_volume=(dailyrec->>'v')::numeric
AND provider_vwap IS NOT DISTINCT FROM(dailyrec->>'vw')::numeric AND provider_close>0 AND share_volume>=0)IS DISTINCT FROM TRUE THEN 'SOURCE_VALUE_OR_RAW_LINK_MISMATCH'
ELSE 'VERIFIED_POINT_AND_SOURCE_LINK' END state FROM joined j)
SELECT selection_order::smallint company_ordinal,session_date,source_day_id,source_row,decode(CASE WHEN session_date=DATE '2026-08-03' THEN legacy_bodysha ELSE source_set_sha256 END,'hex') identity_source_sha256,CASE WHEN session_date=DATE '2026-08-03' THEN legacy_ord ELSE refordinal END identity_source_ordinal,CASE WHEN session_date=DATE '2026-08-03' THEN sha256(convert_to(legacy_rec::text,'UTF8')) ELSE decode(refsha,'hex')END identity_record_sha256,decode(pointsha,'hex') point_record_sha256,raw_record_sha256,
CASE WHEN state='VERIFIED_POINT_AND_SOURCE_LINK' THEN provider_close END raw_close,CASE WHEN state='VERIFIED_POINT_AND_SOURCE_LINK' THEN share_volume END raw_volume,CASE WHEN state='VERIFIED_POINT_AND_SOURCE_LINK' THEN provider_vwap END provider_vwap,state point_source_state,coalesce(actual_source_rows,0)::integer source_rows,CASE WHEN coalesce(actual_source_rows,0)=0 THEN 'ABSENT_FROM_RETAINED_SOURCE' WHEN actual_source_rows=1 THEN 'PRESENT_SINGLE' ELSE 'DUPLICATE_SOURCE_TICKER' END source_presence_state,
CASE WHEN session_date=DATE '2026-08-03' THEN legacy_job ELSE pc->>'source_id' END identity_source_id,CASE WHEN session_date=DATE '2026-08-03' THEN 'acquisition_raw' ELSE 'source_document' END identity_source_relation,(SELECT encode(sha256(convert_to(coalesce(string_agg(record_sha256,E'\n' ORDER BY company_id COLLATE "C",source_set_sha256 COLLATE "C",ticker COLLATE "C"),''),'UTF8')),'hex') FROM points) point_set_manifest_sha256 FROM classified;

DO $insert$DECLARE n bigint;h text;got text;v jsonb;sd bigint;dt date;ph text;counts jsonb;proof jsonb;pin jsonb;cal jsonb;ms numeric;BEGIN
SELECT count(*),min(source_day_id),min(session_date),min(point_set_manifest_sha256) INTO n,sd,dt,ph FROM d02_candidate;
IF n<>3000 OR(SELECT count(DISTINCT company_ordinal)FROM d02_candidate)<>3000 OR(SELECT count(DISTINCT session_date)FROM d02_candidate)<>1 THEN RAISE EXCEPTION 'D02_V2_EXACT_3000_DATE';END IF;
SELECT source_calendar_pins->'sources'->(sd-4)::integer,source_calendar_pins->'calendar'->(sd-4)::integer INTO pin,cal FROM population_top3000_202608_202609_v1.d02_anchor_source_completion_v2 WHERE singleton AND status='STAGED';
IF pin->>'day' IS DISTINCT FROM sd::text OR pin->>'date' IS DISTINCT FROM dt::text THEN RAISE EXCEPTION 'D02_V2_FROZEN_DATE_PIN';END IF;
SELECT encode(sha256(convert_to(string_agg((to_jsonb(q)-'identity_source_id'-'identity_source_relation'-'point_set_manifest_sha256')::text,E'\n' ORDER BY company_ordinal),'UTF8')),'hex') INTO h FROM d02_candidate q;
INSERT INTO population_top3000_202608_202609_v1.d02_anchor_source_point_v2(company_ordinal,session_date,source_day_id,source_row,identity_source_sha256,identity_source_ordinal,identity_record_sha256,point_record_sha256,raw_record_sha256,raw_close,raw_volume,provider_vwap,point_source_state,source_rows,source_presence_state) SELECT company_ordinal,session_date,source_day_id,source_row,identity_source_sha256,identity_source_ordinal,identity_record_sha256,point_record_sha256,raw_record_sha256,raw_close,raw_volume,provider_vwap,point_source_state,source_rows,source_presence_state FROM d02_candidate ON CONFLICT DO NOTHING;
SELECT encode(sha256(convert_to(string_agg(to_jsonb(q)::text,E'\n' ORDER BY company_ordinal),'UTF8')),'hex') INTO got FROM population_top3000_202608_202609_v1.d02_anchor_source_point_v2 q WHERE session_date=dt;
IF got IS DISTINCT FROM h OR(SELECT count(*)FROM population_top3000_202608_202609_v1.d02_anchor_source_point_v2 WHERE session_date=dt)<>3000 THEN RAISE EXCEPTION 'D02_V2_IMMUTABLE_DATA_REPLAY_CONFLICT';END IF;
SELECT jsonb_build_object('point_source_state',(SELECT jsonb_object_agg(point_source_state,x.n) FROM(SELECT point_source_state,count(*)n FROM d02_candidate GROUP BY point_source_state)x),'source_presence_state',(SELECT jsonb_object_agg(source_presence_state,x.n)FROM(SELECT source_presence_state,count(*)n FROM d02_candidate GROUP BY source_presence_state)x))INTO counts;
SELECT coalesce(jsonb_agg(j ORDER BY j::text),'[]'::jsonb)INTO proof FROM(SELECT DISTINCT jsonb_build_object('source_relation',identity_source_relation,'source_id',identity_source_id,'source_sha256',encode(identity_source_sha256,'hex'))j FROM d02_candidate WHERE identity_source_id IS NOT NULL)x;
ms:=extract(epoch FROM(clock_timestamp()-(SELECT started FROM d02_batch_clock)))*1000;
v:=jsonb_build_object('date',dt,'source_day_id',sd,'rows',n,'value_manifest_sha256',h,'point_set_manifest_sha256',ph,'source_pin',pin,'calendar_pin',cal,'source_proof',proof,'state_counts',counts,'assignment_event_id',83312,'claim_event_id',83347);
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.d02_anchor_source_checkpoint_v2 WHERE session_date=dt AND checkpoint_sha256<>encode(sha256(convert_to(v::text,'UTF8')),'hex'))THEN RAISE EXCEPTION 'D02_V2_IMMUTABLE_CHECKPOINT_CONFLICT';END IF;
INSERT INTO population_top3000_202608_202609_v1.d02_anchor_source_checkpoint_v2 VALUES(dt,sd,n,h,ph,pin,cal,proof,counts,ms,83312,83347,clock_timestamp(),encode(sha256(convert_to(v::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
IF(SELECT sum(pg_total_relation_size(oid))FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relname IN('d02_anchor_source_point_v2','d02_anchor_source_checkpoint_v2','d02_anchor_source_completion_v2')AND relkind='r')>67108864 THEN RAISE EXCEPTION 'D02_V2_WHOLE64MIB';END IF;
END $insert$;
SELECT jsonb_build_object('checkpoint',(SELECT to_jsonb(x)FROM population_top3000_202608_202609_v1.d02_anchor_source_checkpoint_v2 x WHERE session_date=(SELECT min(session_date)FROM d02_candidate)),'consumer_rows',(SELECT count(*)FROM population_top3000_202608_202609_v1.working_d02_dated_source_points_v2),'total_staged_rows',(SELECT count(*)FROM population_top3000_202608_202609_v1.d02_anchor_source_point_v2))proof;
COMMIT;
